#include <stdio.h>
#include <stdlib.h>

#define MAXN 1000005

long long L[MAXN];

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    for (int i = 0; i < n; i++) {
        scanf("%lld", &L[i]);
    }

    int left = 0;
    int right = n - 1;
    long long sum_left = L[left];
    long long sum_right = L[right];
    int ops = 0;

    while (left < right) {
        if (sum_left == sum_right) {
            left++;
            right--;
            sum_left = L[left];
            sum_right = L[right];
        } else if (sum_left < sum_right) {
            left++;
            sum_left += L[left];
            ops++;
        } else {
            right--;
            sum_right += L[right];
            ops++;
        }
    }

    printf("%d\n", ops);

    return 0;
}
